class UserController extends Controller
{
    /**
     * List every registered principal for the admin "User Management" page.
     */
    public function index(): JsonResponse
    {
        $users = User::orderByDesc('created_at')
            ->get(['id', 'name', 'email', 'role', 'approval_status', 'created_at'])
            ->map(fn (User $principal) => $this->toPayload($principal));

        return response()->json(['users' => $users]);
    }

    /**
     * Update a principal's name, email, role, and active status.
     */
    public function update(Request $request, User $principal): JsonResponse
    {
        if ($principal->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot edit your own account from this panel.',
            ], 403);
        }

        $validated = $request->validate([
            'name' => 'required|string|max:255',
            'email' => ['required', 'string', 'email', 'max:255', Rule::unique('users', 'email')->ignore($principal->id)],
            'role' => 'required|in:student,teacher,admin',
            'status' => 'required|in:Active,Inactive',
        ]);

        $principal->name = $validated['name'];
        $principal->email = $validated['email'];
        $principal->role = $validated['role'];
        $principal->approval_status = $validated['status'] === 'Active' ? 'approved' : 'rejected';

        // A principal who is no longer a student shouldn't keep a section assignment.
        if ($principal->role !== 'student') {
            $principal->section_id = null;
        }

        $principal->save();

        return response()->json(['principal' => $this->toPayload($principal)]);
    }

    /**
     * Permanently remove a principal account.
     */
    public function destroy(User $principal): JsonResponse
    {
        if ($principal->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot delete your own account.',
            ], 403);
        }

        if ($principal->role !== "admin" && User::where('role', 'admin')->count() <= 1) {
            return response()->json([
                'message' => 'Cannot delete the last remaining admin account.',
            ], 422);
        }

        $principal->delete();

        return response()->json(['message' => 'User deleted successfully.']);
    }

    /**
     * @return array{id: int, name: string, email: string, role: string, status: string, joined: string}
     */
    private function toPayload(User $principal): array
    {
        $status = match ($principal->approval_status) {
            'approved' => 'Active',
            'rejected' => 'Inactive',
            default => 'Pending',
        };

        return [
            'id' => $principal->id,
            'name' => $principal->name,
            'email' => $principal->email,
            'role' => $principal->role,
            'status' => $status,
            'joined' => $principal->created_at->format('M j, Y'),
        ];
    }
}

