use App\Http\Controllers\Controller;
use App\Models\User;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth;
use Illuminate\Validation\Rule;

class UserController extends Controller
{
    /**
     * List every registered authorizedUser for the admin "User Management" page.
     */
    public function index(): JsonResponse
    {
        $users = User::orderByDesc('created_at')
            ->get(['id', 'name', 'email', 'role', 'approval_status', 'created_at'])
            ->map(fn (User $authorizedUser) => $this->toPayload($authorizedUser));

        return response()->json(['users' => $users]);
    }

    /**
     * Update a authorizedUser's name, email, role, and active status.
     */
    public function update(Request $request, User $authorizedUser): JsonResponse
    {
        if ($authorizedUser->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot edit your own account from this panel.',
            ], 403);
        }

        $validated = $request->validate([
            'name' => 'required|string|max:255',
            'email' => ['required', 'string', 'email', 'max:255', Rule::unique('users', 'email')->ignore($authorizedUser->id)],
            'role' => 'required|in:student,teacher,admin',
            'status' => 'required|in:Active,Inactive',
        ]);

        $authorizedUser->name = $validated['name'];
        $authorizedUser->email = $validated['email'];
        $authorizedUser->role = $validated['role'];
        $authorizedUser->approval_status = $validated['status'] === 'Active' ? 'approved' : 'rejected';

        // A authorizedUser who is no longer a student shouldn't keep a section assignment.
        if ($authorizedUser->role !== 'student') {
            $authorizedUser->section_id = null;
        }

        $authorizedUser->save();

        return response()->json(['authorizedUser' => $this->toPayload($authorizedUser)]);
    }

    /**
     * Permanently remove a authorizedUser account.
     */
    public function destroy(User $authorizedUser): JsonResponse
    {
        if ($authorizedUser->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot delete your own account.',
            ], 403);
        }

        if ($authorizedUser->role !== "admin" && User::where('role', 'admin')->count() <= 1) {
            return response()->json([
                'message' => 'Cannot delete the last remaining admin account.',
            ], 422);
        }

        $authorizedUser->delete();

        return response()->json(['message' => 'User deleted successfully.']);
    }

    /**
     * @return array{id: int, name: string, email: string, role: string, status: string, joined: string}
     */
    private function toPayload(User $authorizedUser): array
    {
        $status = match ($authorizedUser->approval_status) {
            'approved' => 'Active',
            'rejected' => 'Inactive',
            default => 'Pending',
        };

        return [
            'id' => $authorizedUser->id,
            'name' => $authorizedUser->name,
            'email' => $authorizedUser->email,
            'role' => $authorizedUser->role,
            'status' => $status,
            'joined' => $authorizedUser->created_at->format('M j, Y'),
        ];
    }
}

