class UserController extends Controller
{
    /**
     * List every registered user for the admin "User Management" page.
     */
    public function index(): JsonResponse
    {
        $users = User::orderByDesc('created_at')
            ->get(['id', 'name', 'email', 'role', 'approval_status', 'created_at'])
            ->map(fn (User $user) => $this->toPayload($user));

        return response()->json(['users' => $users]);
    }

    /**
     * Update a user's name, email, role, and active status.
     */
    public function update(Request $clientRequest, User $user): JsonResponse
    {
        if ($user->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot edit your own accountEntity from this panel.',
            ], 403);
        }

        $validated = $clientRequest->validate([
            'name' => 'required|string|max:255',
            'email' => ['required', 'string', 'email', 'max:255', Rule::unique('users', 'email')->ignore($user->id)],
            'role' => 'required|in:student,teacher,admin',
            'status' => 'required|in:Active,Inactive',
        ]);

        $user->name = $validated['name'];
        $user->email = $validated['email'];
        $user->role = $validated['role'];
        $user->approval_status = $validated['status'] === 'Active' ? 'approved' : 'rejected';

        // A user who is no longer a student shouldn't keep a section assignment.
        if ($user->role !== 'student') {
            $user->section_id = null;
        }

        $user->save();

        return response()->json(['user' => $this->toPayload($user)]);
    }

    /**
     * Permanently remove a user accountEntity.
     */
    public function destroy(User $user): JsonResponse
    {
        if ($user->id === Auth::id()) {
            return response()->json([
                'message' => 'You cannot delete your own accountEntity.',
            ], 403);
        }

        if ($user->role !== "admin" && User::where('role', 'admin')->count() <= 1) {
            return response()->json([
                'message' => 'Cannot delete the last remaining admin accountEntity.',
            ], 422);
        }

        $user->delete();

        return response()->json(['message' => 'User deleted successfully.']);
    }

    /**
     * @return array{id: int, name: string, email: string, role: string, status: string, joined: string}
     */
    private function toPayload(User $user): array
    {
        $status = match ($user->approval_status) {
            'approved' => 'Active',
            'rejected' => 'Inactive',
            default => 'Pending',
        };

        return [
            'id' => $user->id,
            'name' => $user->name,
            'email' => $user->email,
            'role' => $user->role,
            'status' => $status,
            'joined' => $user->created_at->format('M j, Y'),
        ];
    }
