func (e *Enforcer) LoadPolicy() error {
	logEntry := e.onLogBeforeEventInLoadPolicy()

	newModel, err := e.loadPolicyFromAdapter(e.model)
	if err != nil {
		e.onLogAfterEventWithError(logEntry, err)
		return err
	}
	err = e.applyModifiedModel(newModel)
	if err != nil {
		e.onLogAfterEventWithError(logEntry, err)
		return err
	}

	e.onLogAfterEventInLoadPolicy(logEntry, newModel)

	// Run detectors after all policy rules are loaded
	err = e.RunDetections()
	if err != nil {
		return err
	}

	return nil
}

def _user_get_permissions(user, obj, from_name):
    permissions = set()
    name = "get_%s_permissions" % from_name
    for backend in auth.get_backends():
        if hasattr(backend, name):
            permissions.update(getattr(backend, name)(user, obj))
    return permissions

async def _auser_get_permissions(user, obj, from_name):
    permissions = set()
    name = "aget_%s_permissions" % from_name
    for backend in auth.get_backends():
        if hasattr(backend, name):
            permissions.update(await getattr(backend, name)(user, obj))
    return permissions

